import { build } from 'esbuild';
import fs from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { createHash } from 'node:crypto';

const app = fileURLToPath(new URL('../', import.meta.url));
const output = path.resolve(app, '../native');
const ui = await build({
  entryPoints: [path.join(app, 'src/main.tsx')], bundle: true, write: false,
  outdir: 'native', format: 'iife', platform: 'browser', target: 'chrome120', minify: true,
  define: { 'process.env.NODE_ENV': '"production"' }, jsx: 'automatic',
  loader: { '.svg': 'dataurl' },
  legalComments: 'inline', metafile: true,
});
const js = ui.outputFiles.find(file => file.path.endsWith('.js')).text.replace(/<\/script/gi, '<\\/script');
const css = ui.outputFiles.find(file => file.path.endsWith('.css')).text;
const html = '<!doctype html><html lang="zh-CN" data-skilldock-host="mcp"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SkillDock</title><style>' + css + '</style></head><body><div id="root"></div><script>' + js + '</script></body></html>';
await fs.mkdir(output, { recursive: true });
await fs.writeFile(path.join(output, 'ui.html'), html);
const server = await build({ entryPoints: [path.join(app, 'server/native-server.mjs')], outfile: path.join(output, 'server.mjs'),
  bundle: true, platform: 'node', format: 'esm', target: 'node22', minify: true, legalComments: 'inline', metafile: true,
  banner: { js: "// Generated by npm run build:native. Source: assets/app/server/native-server.mjs\nimport { createRequire as __require } from 'node:module'; const require = __require(import.meta.url);" },
});
await fs.copyFile(path.join(app, 'src/native-icon.svg'), path.join(output, 'icon.svg'));
const packages = new Set();
for (const input of [...Object.keys(ui.metafile.inputs), ...Object.keys(server.metafile.inputs)]) {
  const parts = input.split('node_modules/').at(-1).split('/');
  if (input.includes('node_modules/')) packages.add(parts[0].startsWith('@') ? parts.slice(0, 2).join('/') : parts[0]);
}
const notices = [];
for (const name of [...packages].sort()) {
  const root = path.join(app, 'node_modules', name);
  const pkg = JSON.parse(await fs.readFile(path.join(root, 'package.json'), 'utf8'));
  const license = (await fs.readdir(root)).find(file => /^(license|licence|copying)(\.|$)/i.test(file));
  if (!license) throw new Error('Missing bundled dependency license: ' + name);
  notices.push(name + ' ' + pkg.version + '\n\n' + await fs.readFile(path.join(root, license), 'utf8'));
}
await fs.writeFile(path.join(output, 'THIRD_PARTY_NOTICES.txt'), notices.join('\n\n--------\n\n'));
const sha = bytes => createHash('sha256').update(bytes).digest('hex');
const inputs = [...new Set([...Object.keys(ui.metafile.inputs), ...Object.keys(server.metafile.inputs),
  'package-lock.json', 'scripts/native-bundle.mjs', 'src/native-icon.svg'])].filter(name => !name.includes('node_modules/')).sort();
const inputHashes = {}, artifacts = {};
for (const name of inputs) inputHashes[name] = sha(await fs.readFile(path.resolve(app, name)));
for (const name of ['server.mjs', 'ui.html', 'icon.svg', 'THIRD_PARTY_NOTICES.txt']) artifacts[name] = sha(await fs.readFile(path.join(output, name)));
await fs.writeFile(path.join(output, 'build.json'), JSON.stringify({ inputs: inputHashes, artifacts }, null, 2) + '\n');
console.log('Packaged SkillDock native UI and MCP server.');
